 private static void wav(File file,int hz)throws Exception{int rate=48000,length=rate*3*2;ByteBuffer h=ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN);h.put("RIFF".getBytes(StandardCharsets.US_ASCII)).putInt(36+length).put("WAVEfmt ".getBytes(StandardCharsets.US_ASCII)).putInt(16).putShort((short)1).putShort((short)1).putInt(rate).putInt(rate*2).putShort((short)2).putShort((short)16).put("data".getBytes(StandardCharsets.US_ASCII)).putInt(length);ByteBuffer block=ByteBuffer.allocate(rate*2).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<rate;i++)block.putShort((short)(Math.sin(2*Math.PI*hz*i/rate)*6000));try(FileOutputStream out=new FileOutputStream(file)){out.write(h.array());for(int i=0;i<3;i++)out.write(block.array());}}
 private static final String MANIFEST="{\"type\":\"zlplay-library\",\"version\":1,\"order\":[\"Beta\",\"Alpha\"],\"songs\":[{\"id\":\"Alpha\",\"name\":\"Song Alpha\",\"folder\":\"Alpha\",\"source\":\"project.zlplay\",\"originalKey\":\"C#\",\"tonalKey\":\"Db\"},{\"id\":\"Beta\",\"name\":\"Song Beta\",\"folder\":\"Beta\",\"source\":null,\"project\":null,\"rpp\":\"project.rpp\"}]}";
